// MinhaLoja.Domain/Entities/Pedido.cs
namespace MinhaLoja.Domain.Entities;

public class Pedido
{
    private readonly List<ItemPedido> _itens = new();

    public Guid Id { get; private set; }
    public Cliente Cliente { get; private set; }
    public IReadOnlyCollection<ItemPedido> Itens => _itens.AsReadOnly();

    public Pedido(Cliente cliente)
    {
        Id = Guid.NewGuid();
        Cliente = cliente ?? throw new ArgumentNullException(nameof(cliente));
    }

    public void AdicionarItem(Produto produto, int quantidade)
    {
        if (quantidade <= 0)
            throw new PedidoInvalidoException("A quantidade deve ser maior que zero.");

        _itens.Add(new ItemPedido(produto, quantidade));
    }

    public decimal Total() => _itens.Sum(i => i.Produto.Preco * i.Quantidade);
}

// MinhaLoja.Application/Ports/IPedidoRepository.cs
namespace MinhaLoja.Application.Ports;

public interface IPedidoRepository
{
    Task<Pedido?> ObterPorIdAsync(Guid id, CancellationToken ct = default);
    Task SalvarAsync(Pedido pedido, CancellationToken ct = default);
}

// MinhaLoja.Application/UseCases/CriarPedido/CriarPedidoHandler.cs
namespace MinhaLoja.Application.UseCases.CriarPedido;

public class CriarPedidoHandler
{
    private readonly IPedidoRepository _repository;

    public CriarPedidoHandler(IPedidoRepository repository)
    {
        _repository = repository;
    }

    public async Task<CriarPedidoResponse> HandleAsync(
        CriarPedidoCommand command, CancellationToken ct = default)
    {
        var pedido = new Pedido(command.Cliente);

        foreach (var item in command.Itens)
            pedido.AdicionarItem(item.Produto, item.Quantidade);

        if (pedido.Total() <= 0)
            throw new PedidoInvalidoException("Pedido sem itens válidos.");

        await _repository.SalvarAsync(pedido, ct);

        return new CriarPedidoResponse(pedido.Id, pedido.Total());
    }
}

// MinhaLoja.Infrastructure/Persistence/PedidoRepository.cs
using Microsoft.EntityFrameworkCore;
using MinhaLoja.Application.Ports;
using MinhaLoja.Domain.Entities;

namespace MinhaLoja.Infrastructure.Persistence;

public class PedidoRepository : IPedidoRepository
{
    private readonly AppDbContext _context;

    public PedidoRepository(AppDbContext context)
    {
        _context = context;
    }

    public async Task<Pedido?> ObterPorIdAsync(
        Guid id, CancellationToken ct = default)
    {
        return await _context.Pedidos
            .Include(p => p.Itens)
            .FirstOrDefaultAsync(p => p.Id == id, ct);
    }

    public async Task SalvarAsync(Pedido pedido, CancellationToken ct = default)
    {
        _context.Pedidos.Add(pedido);
        await _context.SaveChangesAsync(ct);
    }
}

// MinhaLoja.Infrastructure/DependencyInjection.cs
using Microsoft.Extensions.DependencyInjection;
using MinhaLoja.Application.Ports;
using MinhaLoja.Infrastructure.Persistence;

namespace MinhaLoja.Infrastructure;

public static class DependencyInjection
{
    public static IServiceCollection AddInfrastructure(
        this IServiceCollection services, string connectionString)
    {
        services.AddDbContext<AppDbContext>(o =>
            o.UseSqlServer(connectionString));

        services.AddScoped<IPedidoRepository, PedidoRepository>();

        return services;
    }
}

