using Microsoft.AspNetCore.Mvc;
using MinhaLoja.Application.UseCases.CriarPedido;

namespace MinhaLoja.Api.Controllers;

[ApiController]
[Route("api/pedidos")]
public class PedidosController : ControllerBase
{
    private readonly CriarPedidoHandler _handler;

    public PedidosController(CriarPedidoHandler handler)
    {
        _handler = handler;
    }

    [HttpPost]
    public async Task<IActionResult> Criar(
        CriarPedidoCommand command, CancellationToken ct)
    {
        var response = await _handler.HandleAsync(command, ct);
        return CreatedAtAction(nameof(Criar), new { id = response.Id }, response);
    }
}

